insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('GW', 'GW-P-10', 'Compras de bens do Anexo I 10%', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea a) et Anexo I pour le taux ; art. 19.º e 20.º, n.º 1 pour la déduction.', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-10-SRV', 'Serviços do Anexo I 10%', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea a) et Anexo I, points 5 à 10 pour le taux ; art. 19.º e 20.º, n.º 1 pour la déduction.', 'S', null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-19', 'Compras de bens 19%', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 19.º — droit à déduction de la taxe due ou payée sur les biens acquis à d''autres assujettis du régime normal ; art. 20.º, n.º 1 — déductible pour les opérations taxées ; art. 22.º — exercice au titre de la période où la taxe devient exigible.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-19-IMMO', 'Imobilizações 19%', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 19.º e 20.º, n.º 1 — droit à déduction de la taxe ayant grevé les biens amortissables acquis pour l''activité.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-19-ND', 'Compra 19% não dedutível (art. 21.º)', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 21.º — exclusion du droit à déduction : dépenses de voyage, réception, hébergement, restauration ou loisirs du sujet passif et de son personnel ; véhicules de tourisme, bateaux de plaisance, hélicoptères, avions, motos et leur carburant ; dépenses de luxe ; biens hors commerce. La taxe est une part du coût.', 'S', null, 170, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-19-SRV', 'Serviços exteriores 19%', '{}'::jsonb, null, 'percent', 19, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 19.º e 20.º, n.º 1 — droit à déduction de la taxe supportée sur les services acquis pour les besoins de l''exploitation.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-5-RETIDO', 'Compra a fornecedor do regime simplificado 5%, retida a 100%', '{}'::jsonb, 'Achat facturé « IVA Simplificado » par un fournisseur du régime simplifié, retenu en totalité par le client du régime normal', 'percent', 5, 'purchase', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 7.º, n.º 3, alínea a) — l''acquéreur du régime normal retient la totalité de l''impôt facturé par un fournisseur du régime simplifié (taxe forfaitaire de 5 % de l''art. 38.º) ; art. 39.º — cette facture ne donne de toute façon aucun droit à déduction au client, taxe qui devient donc une part du coût ; art. 7.º, n.º 4 — le montant retenu figure dans un champ propre de la déclaration périodique du client et est reversé au même délai que sa propre TVA (art. 7.º du présent pack) ; art. 7.º, n.º 5 — le fournisseur porte la mention « IVA – Retido ». Le fournisseur est payé hors la part retenue ; celle-ci attend son reversement au compte 4478.', null, null, 190, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-IMP-19', 'Importação 19% (IVA pago na alfândega)', '{}'::jsonb, null, 'percent', 19, 'purchase', 'import', date '2025-01-01', null, 'Código do IVA, art. 17.º — le fait générateur à l''importation est la mise à la consommation, la base étant la valeur en douane ; art. 19.º, n.º 1, alínea c) — l''impôt dû à l''importation est déductible ; art. 26.º, n.º 2 — payé aux services douaniers au dédouanement.', null, null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-P-NR-19', 'Serviços de não residentes 19%, inversão do sujeito passivo', '{}'::jsonb, null, 'percent', 19, 'purchase', 'foreign_services_received', date '2025-01-01', null, 'Código do IVA, art. 7.º, n.º 1 — l''acquéreur de prestations de services réalisées en Guinée-Bissau par un prestataire qui n''y a ni siège, ni établissement stable, ni domicile, ni représentant fiscal (art. 33.º), en devient lui-même l''assujetti ; art. 19.º, n.º 1, alínea b) — la taxe autoliquidée à ce titre est déductible dans les conditions générales. La taxe attend son reversement au compte 4478, sans case propre de ce formulaire.', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-10', 'Vendas de bens do Anexo I 10%', '{}'::jsonb, 'Arroz, farinha e pão ; intrants et matériel agricoles ; matériel solaire et informatique ; presse et activités culturelles', 'percent', 10, 'sale', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea a) et Anexo I — taux de 10 % pour les biens et services énumérés à l''Anexo I : (1) riz, farine et pain, (2) intrants et matériel agricoles (engrais, animaux vivants, produits phytopharmaceutiques, semences, tracteurs et machines agricoles), (3) matériel de production d''énergie solaire, (4) matériel informatique ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux réduit unique compris entre 5 % et 10 %, la liste UEMOA visant les farines et non le riz ni le pain.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-10-SRV', 'Prestações de serviços do Anexo I 10%', '{}'::jsonb, 'Services funéraires ; transport de passagers ; presse et activités culturelles, éducatives et récréatives ; équipements de lutte contre l''incendie ; jurisconsulte ou solicitador ; restauration, hôtellerie et tourisme', 'percent', 10, 'sale', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea a) et Anexo I, points 5 à 10 — services funéraires, transport de passagers, journaux/revues/activités culturelles, éducatives et récréatives, équipements de lutte contre l''incendie, services de jurisconsulte ou de solicitador, restauration/hôtellerie/tourisme.', 'S', null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-19', 'Vendas de bens 19%', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA au compte 4431', 'percent', 19, 'sale', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea b) — taux de 19 % pour les importations, livraisons de biens et prestations de services hors Anexo I ; mise en application au 1er janvier 2025 (Despacho n.º 130/GMF/2024) ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 %.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-19-SRV', 'Prestações de serviços 19%', '{}'::jsonb, 'Prestations de services au taux normal, TVA au compte 4432', 'percent', 19, 'sale', 'domestic', date '2025-01-01', null, 'Código do IVA, art. 18.º, n.º 1, alínea b) ; art. 11.º, n.º 1, alínea b) — le fait générateur d''une prestation de services est son exécution ; art. 12.º — la facture émise dans le délai devance ce fait générateur.', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-EXO', 'Operação interna isenta (art. 13.º e 14.º)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2025-01-01', null, 'Código do IVA, art. 13.º — opérations internes exonérées : médicaments et produits pharmaceutiques de l''Anexo II, soins médicaux et paramédicaux à finalité exclusivement thérapeutique et transport de blessés/malades, enseignement scolaire et universitaire reconnu, gaz à usage domestique, opérations financières et d''assurance non rémunérées par une commission explicite, opérations immobilières sur des immeubles d''habitation (hors hébergement hôtelier) ; art. 14.º — importations exonérées symétriques ; art. 13.º, n.º 2 — aucune exonération administrative en dehors du Code. Sans droit à déduction, sauf le cas particulier de l''art. 20.º, n.º 2, alínea d), non repris ici faute de golden le justifiant.', 'E', null, 60, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'civa', null, null, null, null),
  ('GW', 'GW-S-EXP', 'Exportação isenta', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2025-01-01', null, 'Código do IVA, art. 15.º, n.º 1, alínea a) — sont exonérées la transmission de biens destinés à l''exportation et les prestations de services que la législation douanière assimile à des exportations ; art. 18.º, n.º 1, alínea c) — taux de 0 % ; art. 20.º, n.º 2, alínea a) — droit à déduction de la taxe d''amont ; Despacho MF n.º 1/2023, art. 7.º, n.º 1, alínea b) — série B des factures d''exportation.', 'G', null, 50, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'civa', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
