insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('GW', 'GW-IVA', 'Declaração periódica de Imposto sobre o Valor Acrescentado (regime normal)', array['month']::declaration_period[], 'month'::declaration_period, date '2025-01-01', null, 'Código do IVA, art. 31.º — les assujettis du régime normal (art. 6.º, n.º 1, alínea a) déposent, au plus tard le 15 du mois suivant, une déclaration périodique des opérations imposables du mois précédent, obligatoire même sans opération ; art. 31.º, n.º 2 — le modèle de la déclaration est approuvé par le directeur général de la DGCI et n''a pas été publié : les cases de ce formulaire suivent le contenu que l''article impose (impôt dû ou crédit, éléments de calcul) et non la numérotation de l''imprimé. Le régime simplifié (art. 38.º à 42.º) dépose une déclaration trimestrielle distincte, propre à sa taxe forfaitaire de 5 %, que ce pack ne construit pas (voir README) ; les opérations isolées (art. 6.º, n.º 1, alíneas b) et d) suivent une déclaration avulsa distincte (art. 32.º), également hors de ce formulaire.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Código do IVA, art. 31.º, n.º 1 — dépôt au plus tard le 15 du mois suivant celui auquel se rapportent les opérations ; art. 25.º, n.º 1 — le paiement suit le même délai que le dépôt de la déclaration.', 'civa', null)
