  ('GW', 'GW-IVA', 'CA19', 'base', 'Operações tributáveis à taxa normal de 19%', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 — la déclaration porte les éléments qui ont servi de base au calcul de l''impôt ; art. 18.º, n.º 1, alínea b) pour le taux. Le modèle officiel de l''imprimé, approuvé par le directeur général de la DGCI (art. 31.º, n.º 2), n''est pas publié : les cases de ce formulaire suivent le contenu que l''article impose et non la numérotation de l''imprimé.', 'civa'),
  ('GW', 'GW-IVA', 'CA10', 'base', 'Operações tributáveis à taxa reduzida de 10%', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 et art. 18.º, n.º 1, alínea a) et Anexo I.', 'civa'),
  ('GW', 'GW-IVA', 'EXP', 'base', 'Exportações isentas com direito à dedução', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 15.º et art. 20.º, n.º 2, alínea a) — exonération des exportations ouvrant droit à déduction.', 'civa'),
  ('GW', 'GW-IVA', 'EXO', 'base', 'Outras operações internas isentas', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 13.º et art. 14.º pour la liste des opérations exonérées sans droit à déduction.', 'civa'),
  ('GW', 'GW-IVA', 'CAT', 'total', 'Montante total das operações realizadas', '{}'::jsonb, 50, null, array['CA19', 'CA10', 'EXP', 'EXO']::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 — indication des éléments de calcul de l''impôt et du crédit.', 'civa'),
  ('GW', 'GW-IVA', 'TVA19', 'tax', 'Imposto exigível à taxa de 19%', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 11.º et 12.º pour l''exigibilité.', 'civa'),
  ('GW', 'GW-IVA', 'TVA10', 'tax', 'Imposto exigível à taxa de 10%', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 18.º, n.º 1, alínea a).', 'civa'),
