  ('GW', 'GW-IVA', 'TVAB', 'total', 'Total do imposto exigível', '{}'::jsonb, 90, null, array['TVA19', 'TVA10', 'IVARET']::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2.', 'civa'),
  ('GW', 'GW-IVA', 'DEDIMMO', 'tax', 'IVA dedutível sobre imobilizações', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 19.º e 20.º para o direito à dedução.', 'civa'),
  ('GW', 'GW-IVA', 'DEDBS', 'tax', 'IVA dedutível sobre bens, serviços e importações', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Código do IVA, art. 31.º, n.º 2 ; art. 19.º e 20.º ; art. 22.º — exercice au titre de la période où l''impôt déductible devient exigible ou de la période suivante.', 'civa'),
