  ('GW', 'GW-IVA', 'NET', 'total', 'Imposto líquido a pagar', '{}'::jsonb, 130, null, array['TVAB']::text[], array['DEDT']::text[], null, null, true, false, null, 'Código do IVA, art. 22.º, n.º 1 — l''impôt dû résulte de la soustraction, sur la période, du montant déductible exigible au montant global de l''impôt dû sur les opérations imposables ; art. 25.º, n.º 1 pour le paiement.', 'civa'),
  ('GW', 'GW-IVA', 'CRED', 'total', 'Crédito de IVA a reportar', '{}'::jsonb, 140, null, array['DEDT']::text[], array['TVAB']::text[], null, null, true, false, null, 'Código do IVA, art. 24.º, n.º 1 — l''excédent de taxe déductible sur la taxe due au titre d''une période est reporté sur les périodes suivantes ; art. 24.º, n.º 2 — au-delà de douze mois et d''un crédit supérieur à 1 000 000 FCFA, une note de crédit fiscal peut être demandée pour compensation.', 'civa')
