update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}-{NNNNNNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Despacho MF n.º 1/2023 (Regulamento das Faturas), art. 11.º, n.º 1 — a numeração das faturas é atribuída pela DGCI dans l''ordre croissant, de 1 à 9 999 999 999, « sans interruptions ni répétitions » ; art. 11.º, n.º 2 — le numéro est précédé d''une lettre selon le mode d''émission (K- Kontaktu, I- logiciel, T- imprimerie, C- contingence) et, par l''art. 7.º, n.º 1, d''une série selon la nature de l''opération (A ventes internes, B exportations, C importations, D notes de crédit, E contingence, F guides de transport). {CODE} tient la lettre et la série ; le format ne peut pas exprimer la lettre du mode d''émission, qui n''est connue qu''au moment de l''autorisation DGCI.',
  numbering_source_key          = 'regulamento-faturas',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Código do IVA, art. 11.º — l''impôt devient exigible à la livraison du bien, à l''exécution du service ou à l''importation ; art. 12.º — lorsque l''opération oblige à émettre une facture (art. 29.º, ce qui est la règle générale), l''impôt devient exigible à l''émission de la facture si le délai est respecté, au terme du délai s''il ne l''est pas, ou à l''encaissement s''il précède la facture. invoice_if_issued dit le principe de l''art. 11.º et la facture qui le devance selon l''art. 12.º.',
  tax_point_source_key          = 'civa',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Código do IVA, art. 29.º, n.º 3 — le contenu des factures et les conditions de leur émission sont fixés par arrêté du ministre des Finances, délégation exercée par le Despacho MF n.º 1/2023 (Regulamento das Faturas), obligatoire pour tout assujetti depuis la mise en application de l''IVA le 1er janvier 2025 (Despacho n.º 130/GMF/2024) : toute facture est autorisée au préalable par la DGCI (numérotation, série, code QR et URL de vérification, art. 7.º et 11.º du règlement) et émise en ligne sur Kontaktu, par un logiciel autorisé ou par une imprimerie agréée — un mécanisme d''autorisation préalable et non un profil structuré au sens d''EN 16931, ce qui laisse `profile` vide. L''identifiant fiscal porté sur la facture est le NIF (art. 7.º, n.º 3, alínea a) du règlement), qui n''a pas de code ISO 6523.',
  einvoice_source_key           = 'regulamento-faturas',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'GW';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('GW', 'exempt', 'exempt', 'Operação isenta de imposto sobre o valor acrescentado — artigo 13.º ou 14.º do Código do IVA.', '{}'::jsonb, 10, date '1970-01-01', null, 'Despacho MF n.º 1/2023, art. 7.º, n.º 3, alínea h) — en cas d''exonération, la facture indique la disposition légale applicable ; Código do IVA, art. 13.º (opérations internes exonérées) et art. 14.º (importations exonérées).'),
  ('GW', 'export', 'export', 'Exportação isenta de imposto sobre o valor acrescentado, com direito à dedução — artigo 15.º do Código do IVA.', '{}'::jsonb, 20, date '1970-01-01', null, 'Código do IVA, art. 15.º — exonération des exportations et opérations assimilées ; art. 20.º, n.º 2, alínea a) — droit à déduction sur ces opérations ; Despacho MF n.º 1/2023, art. 7.º, n.º 1, alínea b) — série B pour les factures d''exportation.'),
  ('GW', 'small_business', 'small_business', 'IVA Simplificado – Não confere direito à dedução.', '{}'::jsonb, 30, date '1970-01-01', null, 'Código do IVA, art. 39.º — les factures des contribuables du régime simplifié (art. 38.º) ne donnent au client aucun droit à déduction et portent expressément cette mention ; Despacho MF n.º 1/2023, art. 8.º, n.º 1, alínea f).'),
  ('GW', 'reverse_charge', 'reverse_charge', 'IVA – Retido.', '{}'::jsonb, 40, date '1970-01-01', null, 'Código do IVA, art. 7.º, n.º 3 à 5 — l''acquéreur du régime normal retient la totalité de l''impôt facturé par un fournisseur du régime simplifié ou du régime normal classé « à risque » par le directeur général de la DGCI ; le fournisseur porte la mention « IVA – Retido » ; Despacho MF n.º 1/2023, art. 7.º, n.º 3, alínea i).')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
